<script setup lang="ts">
import { ref } from 'vue';
import { Head, useForm, router } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import Icon from '../../components/Icon.vue';
import FormErrors from '../../components/FormErrors.vue';
import Pagination from '../../components/Pagination.vue';
import { initials, type Person, type Pagination as Paginated } from '../../types';
defineProps<{ users: Paginated<Person> }>();
const form = useForm({ name: '', email: '', password: '', role: 'user' });
const errors = ref<Record<string, string>>({});
const busy = ref(false);
function update(user: Person, role = user.role!, is_active = user.is_active!) { errors.value = {}; busy.value = true; router.patch(`/support/users/${user.id}`, { role, is_active }, { preserveScroll: true, onError: value => { errors.value = value; }, onFinish: () => { busy.value = false; } }); }
</script>
<template><Head title="Usuarios" /><AppLayout title="Usuarios" section="Administración"><div class="page-heading"><div><div class="eyebrow">LAS PERSONAS DETRÁS DEL EQUIPO</div><h1>Usuarios<span class="heading-dot">.</span></h1><p>Gestiona el acceso de los solicitantes y el equipo de soporte.</p></div></div><FormErrors :errors="errors" /><div class="admin-grid"><div class="panel admin-list"><div class="table-scroll"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="user in users.data" :key="user.id"><td><div class="person-info"><span class="avatar" :class="`tone-${user.id % 4}`">{{ initials(user.name) }}</span><div><strong>{{ user.name }}</strong><small>{{ user.email }}</small></div></div></td><td><select :value="user.role" :aria-label="`Rol de ${user.name}`" :disabled="busy" @change="update(user, ($event.target as HTMLSelectElement).value)"><option value="user">Usuario</option><option value="support">Soporte</option></select></td><td><span :class="['active-label', { 'inactive-label': !user.is_active }]"><span class="status-dot" :class="user.is_active ? 'blue-dot' : ''"></span>{{ user.is_active ? 'Activo' : 'Inactivo' }}</span></td><td><button class="btn secondary small" :disabled="busy" @click="update(user, user.role, !user.is_active)">{{ user.is_active ? 'Desactivar' : 'Activar' }}</button></td></tr></tbody></table></div><div class="table-bottom"><span>{{ users.total }} usuarios</span><Pagination :links="users.links" /></div></div><form class="panel admin-form" @submit.prevent="form.post('/support/users', { onSuccess: () => form.reset() })"><h2>Crear una cuenta</h2><FormErrors :errors="form.errors" /><label class="field">Nombre completo<input v-model="form.name" required maxlength="100" autocomplete="name" /></label><label class="field">Correo electrónico<input v-model="form.email" required type="email" autocomplete="email" /></label><label class="field">Contraseña inicial<input v-model="form.password" required type="password" minlength="10" autocomplete="new-password" /><span class="helper">Mínimo 10 caracteres con letras y números.</span></label><label class="field">Rol<select v-model="form.role"><option value="user">Usuario</option><option value="support">Soporte</option></select></label><button class="btn primary" :disabled="form.processing"><Icon name="Plus" />{{ form.processing ? 'Creando…' : 'Crear cuenta' }}</button></form></div></AppLayout></template>
